import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type CurrencyConversion = {
  /**
   * A unique identifier that is used to identify and reference an instance of this resource. It is
   * generated by Global Payments to identify the currency conversion details used with this
   * transaction.
   */
  id?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const currencyConversionProperties: s.Shape<CurrencyConversion> = {
  id: s.optional(s.string()),
};

export const currencyConversionInternalSchema: Schema<CurrencyConversion> = s.object<CurrencyConversion>(
  currencyConversionProperties,
  { additionalProperties: s.json() },
);

export const currencyConversionSchema: Schema<CurrencyConversion> = s.lazySchema(() =>
  s.object<CurrencyConversion>(
    {
      ...currencyConversionProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
